const CACHE='dailytally-shell-theme-4',FILES=['/','/auth.js','/refresh.js','/mobile.css','/site.webmanifest','/assets/icon.png','/assets/favicon.ico','/assets/apple-touch-icon.png','/assets/android-chrome-192x192.png','/assets/android-chrome-512x512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('dailytally-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/')||!FILES.includes(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(url.pathname,copy)))}return response}).catch(()=>caches.open(CACHE).then(cache=>cache.match(url.pathname))))});

self.addEventListener('push',event=>{event.waitUntil((async()=>{let payload={};try{payload=event.data?.json()||{}}catch{}await self.registration.showNotification(payload.title||'DailyTally',{body:payload.body||'You have a reminder.',tag:payload.tag||'dailytally-reminder',icon:'/assets/android-chrome-192x192.png',badge:'/assets/android-chrome-192x192.png',data:{url:'/?reminders=1'}})})())});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of windows){if(new URL(client.url).origin===self.location.origin){await client.focus();client.postMessage({type:'OPEN_REMINDERS'});return}}await self.clients.openWindow('/?reminders=1')})())});
